<div class="form-grid"><div class="form-group"><label for="name">Full name</label><input class="form-control" id="name" name="name" value="{{ old('name', $coach->name ?? '') }}" required></div><div class="form-group"><label for="email">Email</label><input class="form-control" id="email" name="email" type="email" value="{{ old('email', $coach->email ?? '') }}" required></div><div class="form-group"><label for="phone">Phone</label><input class="form-control" id="phone" name="phone" value="{{ old('phone', $coach->phone ?? '') }}"></div><div class="form-group"><label for="specialty">Specialty</label><input class="form-control" id="specialty" name="specialty" value="{{ old('specialty', $coach->specialty ?? '') }}" required></div><div class="form-group"><label for="sport_id">Assigned sport</label><select class="form-control" id="sport_id" name="sport_id" required><option value="">Select sport</option>@foreach ($sports as $sport)<option value="{{ $sport->id }}" @selected((string) old('sport_id', $coach->sport_id ?? '') === (string) $sport->id)>{{ $sport->name }}</option>@endforeach</select></div><div class="form-group"><label for="coach_type">Coach type</label><select class="form-control" id="coach_type" name="coach_type">@foreach ($coachTypes as $coachType)<option value="{{ $coachType }}" @selected(old('coach_type', $coach->coach_type ?? 'Head Coach') === $coachType)>{{ $coachType }}</option>@endforeach</select></div><div class="form-group"><label for="status">Status</label><select class="form-control" id="status" name="status">@foreach ($statuses as $status)<option value="{{ $status }}" @selected(old('status', $coach->status ?? 'Active') === $status)>{{ $status }}</option>@endforeach</select></div></div><div class="event-actions"><button class="button" type="submit">{{ isset($coach) ? 'Update Coach' : 'Save Coach' }}</button><a class="button button-muted" href="{{ route('coaches.index') }}">Cancel</a></div>
